function quarterMs(bpm){ bpm=+bpm; if(!(bpm>0)) return {error:'BPM须为正'}; return 60000/bpm; }
function noteMs(bpm, beats){ var q=quarterMs(bpm); if(typeof q==='object') return q; return q*beats; }
function bpmFromQuarterMs(ms){ ms=+ms; if(!(ms>0)) return {error:'毫秒须为正'}; return 60000/ms; }
function noteName(beats){ var map={0.25:'十六分音符',0.5:'八分音符',1:'四分音符',2:'二分音符',4:'全音符'}; return map[beats]||(beats+' 拍'); }
var EXPORTS={quarterMs:quarterMs, noteMs:noteMs, bpmFromQuarterMs:bpmFromQuarterMs, noteName:noteName};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TempoForgePure = EXPORTS; }
